#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int concatenatedBinary(int n) {
        const long long MOD = 1000000007;
        long long ans = 0;
        int bits = 0;
        for (int i = 1; i <= n; ++i) {
            if ((i & (i - 1)) == 0) ++bits;
            ans = ((ans << bits) | i) % MOD;
        }
        return (int)ans;
    }
};
